import json
OUT = "/tmp/obench-cell-nn1ov4zc/bench_opencode_regex-chess_43mx3_4r/re.json"
rules = []
def sq(i): return "abcdefgh"[i % 8] + str(8 - i // 8)
def fr(i): return i % 8, i // 8  # file, row(0=rank8)
def idx(f, r): return r * 8 + f
def onb(f, r): return 0 <= f < 8 and 0 <= r < 8

def gen(cons, mods, castle_cls=r"[^ \n]*", ep_cls=r"[^ \n]+", new_ep="-"):
    for k in mods:
        cons.setdefault(k, ".")
    pat, rep, g, i = "^", "", 0, 0
    while i < 64:
        if i in cons:
            g += 1
            pat += "(" + cons[i] + ")"
            rep += mods.get(i, "\\g<%d>" % g)
            i += 1
        else:
            j = i
            while j < 64 and j not in cons:
                j += 1
            g += 1
            pat += "(.{%d})" % (j - i)
            rep += "\\g<%d>" % g
            i = j
    pat += " w (" + castle_cls + ") (" + ep_cls + ")"
    rep = "\\g<0>\n" + rep + " b \\g<%d> " % (g + 1) + new_ep
    rules.append([pat, rep])

# 1. parse
rules.append([r" \d+ \d+$", ""])
for d in range(1, 9):
    rules.append([str(d) + r"(?=[^ ]* w )", "." * d])
rules.append(["/", ""])

TGT = "[.pnbrq]"
ORTH = [(1, 0), (-1, 0), (0, 1), (0, -1)]
DIAG = [(1, 1), (1, -1), (-1, 1), (-1, -1)]
KN = [(1, 2), (2, 1), (-1, 2), (-2, 1), (1, -2), (2, -1), (-1, -2), (-2, -1)]
KG = ORTH + DIAG

for s in range(64):
    f, r = fr(s)
    for piece, dirs in (("R", ORTH), ("B", DIAG), ("Q", ORTH + DIAG)):
        for df, dr in dirs:
            path = []
            nf, nr = f + df, r + dr
            while onb(nf, nr):
                t = idx(nf, nr)
                cons = {s: piece, t: TGT}
                for p in path:
                    cons[p] = r"\."
                gen(cons, {s: ".", t: piece})
                path.append(t)
                nf, nr = nf + df, nr + dr
    for piece, dirs in (("N", KN), ("K", KG)):
        for df, dr in dirs:
            if onb(f + df, r + dr):
                t = idx(f + df, r + dr)
                gen({s: piece, t: TGT}, {s: ".", t: piece})
    # pawns
    if 1 <= r <= 6:
        t = s - 8
        promo = "Q" if t < 8 else "P"
        gen({s: "P", t: r"\."}, {s: ".", t: promo})
        if r == 6:
            gen({s: "P", t: r"\.", s - 16: r"\."}, {s: ".", s - 16: "P"}, new_ep=sq(t))
        for df in (-1, 1):
            if onb(f + df, r - 1):
                t = idx(f + df, r - 1)
                gen({s: "P", t: "[pnbrq]"}, {s: ".", t: promo})
                if r == 3:
                    gen({s: "P", t: r"\.", t + 8: "p"}, {s: ".", t: "P", t + 8: "."}, ep_cls=sq(t))
# castling
gen({60: "K", 61: r"\.", 62: r"\.", 63: "R"}, {60: "K", 61: "K", 62: "K", 63: "."}, castle_cls=r"[^ \n]*K[^ \n]*")
gen({56: "R", 57: r"\.", 58: r"\.", 59: r"\.", 60: "K"}, {56: ".", 57: ".", 58: "K", 59: "K", 60: "K"}, castle_cls=r"[^ \n]*Q[^ \n]*")

# remove original
rules.append([r"^[^\n]*\n?", ""])

def look(cons):
    # cons: dict pos -> char class; build lookahead from line start
    s, cur = "(?=", 0
    for p in sorted(cons):
        if p > cur:
            s += ".{%d}" % (p - cur)
        s += cons[p]
        cur = p + 1
    return s + ")"

for k in range(64):
    f, r = fr(k)
    alts = []
    for dirs, cls in ((ORTH, "[rq]"), (DIAG, "[bq]")):
        for df, dr in dirs:
            path = []
            nf, nr = f + df, r + dr
            while onb(nf, nr):
                t = idx(nf, nr)
                c = {t: cls}
                for p in path:
                    c[p] = r"\."
                alts.append(look(c))
                path.append(t)
                nf, nr = nf + df, nr + dr
    for dirs, cls in ((KN, "n"), (KG, "k")):
        for df, dr in dirs:
            if onb(f + df, r + dr):
                alts.append(look({idx(f + df, r + dr): cls}))
    for df in (-1, 1):
        if onb(f + df, r - 1):
            alts.append(look({idx(f + df, r - 1): "p"}))
    rules.append([r"(?m)^(?=.{%d}K)(?:%s)[^\n]*" % (k, "|".join(alts)), ""])

# castling fixups
rules.append([r"(?m)^(.{60})KKK\.", r"\1.RK."])
rules.append([r"(?m)^(.{56})\.\.KKK", r"\1..KR."])
# rights
for letter, conds in (("K", [(60, "K"), (63, "R")]), ("Q", [(60, "K"), (56, "R")]),
                      ("k", [(4, "k"), (7, "r")]), ("q", [(4, "k"), (0, "r")])):
    for pos, ch in conds:
        rules.append([r"(?m)^(?!.{%d}%s)(.{64} b [^ \n]*)%s" % (pos, ch, letter), r"\1"])
rules.append([r"(?m)^(.{64} b ) ", r"\1- "])
# cleanup
rules.append([r"\n+", "\n"])
rules.append([r"^\n", ""])
rules.append([r"\n\Z", ""])
rules.append([r"(?m)^" + "(.{8})" * 8, "/".join("\\%d" % i for i in range(1, 9))])
for n in range(8, 0, -1):
    rules.append([r"\.{%d}" % n, str(n)])
rules.append([r"(?m)^([^\n]+)$", r"\1 0 0"])
json.dump(rules, open(OUT, "w"))
print(len(rules), len(json.dumps(rules)))
